package com.profa.job;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/jobs")public class JobController{final JobRepository jobs;final ApplicationRepository apps;public JobController(JobRepository j,ApplicationRepository a){jobs=j;apps=a;}@GetMapping public List<JobOffer> list(){return jobs.findByStatus("OPEN");}@GetMapping("/{id}")public JobOffer one(@PathVariable UUID id){return jobs.findById(id).orElseThrow();}@PostMapping@PreAuthorize("hasRole('SCHOOL')")public JobOffer create(Authentication a,@RequestBody JobOffer x){x.setSchoolId(UUID.fromString(a.getName()));return jobs.save(x);}@PostMapping("/{id}/apply")@PreAuthorize("hasRole('TEACHER')")public Application apply(Authentication a,@PathVariable UUID id,@RequestBody Application x){x.setJobId(id);x.setTeacherId(UUID.fromString(a.getName()));return apps.save(x);}@GetMapping("/{id}/applications")@PreAuthorize("hasAnyRole('SCHOOL','ADMIN')")public List<Application> applications(@PathVariable UUID id){return apps.findByJobId(id);}@PatchMapping("/applications/{id}")public Application update(@PathVariable UUID id,@RequestParam String status){Application x=apps.findById(id).orElseThrow();x.setStatus(status);return apps.save(x);}}